python3 - <<'PY'
from pathlib import Path
css=Path('apps/mobile/src/theme/theme.css')
s=css.read_text()
old=""".setup-context__back {
  background: transparent;
  flex: 0 0 auto;
  border: 0;
  color: var(--lcl-color-accent);
  cursor: pointer;
  font-weight: 800;
  padding: var(--lcl-spacing-sm) 0;
}"""
new=""".setup-context__back {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--lcl-color-accent);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  font-weight: 800;
  min-height: var(--lcl-size-control-min-height);
  padding: var(--lcl-spacing-sm) 0;
}"""
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old2="""  .setup-top-nav__item {
    font-size: var(--lcl-font-size-xs);
    min-height: var(--lcl-size-compact-control-min-height);
    padding: 0;
  }"""
new2="""  .setup-top-nav__item {
    font-size: var(--lcl-font-size-xs);
    min-height: var(--lcl-size-control-min-height);
    padding: 0;
  }"""
assert s.count(old2)==1, s.count(old2)
css.write_text(s.replace(old2,new2))

test=Path('apps/mobile/e2e/responsive.spec.ts')
t=test.read_text()
needle="""    await expect(
      page.getByRole('button', { name: 'Shelly', exact: true })
    ).toHaveAttribute('aria-current', 'page');
    await expect(page.getByRole('region', { name: 'Gniazdka Shelly' })).toBeVisible();"""
replacement="""    await expect(
      page.getByRole('button', { name: 'Shelly', exact: true })
    ).toHaveAttribute('aria-current', 'page');
    const setupTouchTargetHeights = await page
      .locator('.setup-context__back, .setup-top-nav__item')
      .evaluateAll((elements) =>
        elements.map((element) => Math.round(element.getBoundingClientRect().height))
      );
    expect(Math.min(...setupTouchTargetHeights)).toBeGreaterThanOrEqual(44);
    await expect(page.getByRole('region', { name: 'Gniazdka Shelly' })).toBeVisible();"""
assert t.count(needle)==1, t.count(needle)
test.write_text(t.replace(needle,replacement))
PY
